#include <algorithm>
#include <cctype>
#include <sstream>
#include <string>
#include <vector>

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

bool matches(const std::string& item, const std::string& filter)
{
    const std::string hay{ lower(item) };
    std::istringstream words{ lower(filter) };
    for (std::string w; words >> w;)
        if (hay.find(w) == std::string::npos) return false;
    return true;
}

std::vector<int> visibleItems(const std::vector<std::string>& items, const std::string& filter)
{
    std::vector<int> out;
    for (int i{ 0 }; i < static_cast<int>(items.size()); ++i)
        if (matches(items[static_cast<std::size_t>(i)], filter)) out.push_back(i);
    return out;
}

int keepSelection(const std::vector<int>& visible, int selected)
{
    if (std::find(visible.begin(), visible.end(), selected) != visible.end()) return selected;
    return visible.empty() ? -1 : visible.front();
}

unitTests:
const std::vector<std::string> assets{ "big_mossy_rock", "small_rock", "Tree_Oak", "tree_pine", "Big_Tree" };
TEST("words in any order") { CHECK(matches("big_mossy_rock", "rock BIG")); CHECK(!matches("big_mossy_rock", "rock small")); }
TEST("empty filter") { CHECK(matches("anything", "")); CHECK(matches("anything", "   ")); }
TEST("visible items") { CHECK_EQ(visibleItems(assets, "tree"), (std::vector<int>{ 2, 3, 4 })); CHECK_EQ(visibleItems(assets, "big"), (std::vector<int>{ 0, 4 })); CHECK(visibleItems(assets, "lava").empty()); }
TEST("keep the selection") { CHECK_EQ(keepSelection({ 2, 3, 4 }, 3), 3); CHECK_EQ(keepSelection({ 2, 3, 4 }, 0), 2); CHECK_EQ(keepSelection({}, 1), -1); }

